const body = $input.first().json.body || $input.first().json;

return [{
  json: {
    body: body,
    niche: body.niche,
    selectedVideoId: body.selectedVideoId,
    videoTitle: body.videoTitle || '',
    videoAuthor: body.videoAuthor || '',
    videoHashtags: body.videoHashtags || [],
    videoViews: body.videoViews || '',
    videoLikes: body.videoLikes || '',
    creatorId: body.creatorId,
    userPrompt: body.userPrompt || ''
  }
}];

const allInputs = $input.all();
const previousScripts = allInputs.filter(i => i.json.script_content !== null && i.json.script_content !== undefined);
const previousScriptsText = previousScripts.length > 0
  ? '\nAVOID repeating these previous scripts:\n' + previousScripts.map(s => s.json.script_content).join('\n---\n')
  : '';

const data = $input.first().json;

const videoTitle    = data.video_title    || data.videoTitle    || '';
const videoAuthor   = data.video_author   || data.videoAuthor   || '';
const videoHashtags = data.video_hashtags || data.videoHashtags || [];
const videoViews    = data.video_views    || data.videoViews    || '';
const videoLikes    = data.video_likes    || data.videoLikes    || '';

const hashtagStr = Array.isArray(videoHashtags) ? videoHashtags.join(', ') : String(videoHashtags);

const videoContext = videoTitle
  ? `Title: "${videoTitle}"\nCreator: ${videoAuthor}\nHashtags: ${hashtagStr}\nViews: ${videoViews} | Likes: ${videoLikes}`
  : `Video ID: ${data.selected_video_id}`;

return [{
  json: {
    niche: data.niche,
    sessionId: data.session_id,
    creatorId: data.creator_id,
    userPrompt: data.user_prompt || '',
    videoContext,
    previousScriptsText
  }
}];

parameters.value:
==You are a viral TikTok scriptwriter.

A creator has selected this TRENDING VIDEO as inspiration:
{{ $json.videoContext }}

Your job: write an ORIGINAL 30-60 second TikTok script for the **{{ $json.niche }}** niche that is INSPIRED by the above video — not a copy. Borrow its energy, hook style, and what made it go viral. Make it fresh.

{{ $json.userPrompt ? "Creator's specific angle: " + $json.userPrompt : '' }}
{{ $json.previousScriptsText ? $json.previousScriptsText + "\n\nYour script MUST have a different hook, different structure, and different ideas than the rejected scripts above." : '' }}

Output ONLY the spoken script. No markdown, no labels, no explanations.

parameters.jsCode:
const response = $input.first().json.response;
let scriptJson = {};
try {
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  if (jsonMatch) { scriptJson = JSON.parse(jsonMatch[0]); }
} catch(e) { scriptJson = { full_script: response }; }
const promptData = $('⚙️ Prepare AI Script Prompt').item.json;
const scriptContentSql = response.replace(/'/g, "''");
return [{
  json: {
    scriptId: 'script_' + Date.now(),
    sessionId: promptData.sessionId || '',
    creatorId: promptData.creatorId || '',
    scriptContent: response,
    scriptContentSql: scriptContentSql,
    scriptJson: JSON.stringify(scriptJson).replace(/'/g, "''"),
    hook: scriptJson.hook || '',
    cta: scriptJson.cta || '',
    hashtags: scriptJson.hashtags || []
  }
}];

const webhookData = $('🎯 Webhook: Script Approve/Decline').item.json;
const sessionId = webhookData.body.sessionId;
const creatorId = webhookData.body.creatorId;

return [{
  json: {
    session_id: sessionId,
    creator_id: creatorId,
    niche: webhookData.body.niche || 'tech',
    selected_video_id: webhookData.body.selectedVideoId || '',
    script_json: {}
  }
}];

const data = $input.first().json;
const scriptJson = typeof data.script_json === 'string'
  ? JSON.parse(data.script_json || '{}')
  : (data.script_json || {});
const videoPrompt = `Create a 45-second vertical TikTok video.\nHook: ${scriptJson.hook || 'Engaging opening'}\nMain content: ${scriptJson.middle || data.script_content || 'Core content'}\nVisual directions: ${scriptJson.visual_directions || 'Dynamic visuals'}\nMusic vibe: ${scriptJson.music_vibe || 'Trending audio'}`;
return [{
  json: {
    videoPrompt,
    sessionId: data.session_id,
    creatorId: data.creator_id,
    scriptJson
  }
}];

const falOutput = $input.first().json;
const prepData = $('⚙️ Prepare Video Generation Prompt').item.json;
const videoUrl = falOutput.video?.url || '';
return [{
  json: {
    videoId: 'video_' + Date.now(),
    videoUrl: videoUrl,
    sessionId: prepData.sessionId,
    creatorId: prepData.creatorId,
    promptUsed: prepData.videoPrompt.replace(/'/g, "''")
  }
}];

const runId = $('🗄️ Init Run in PostgreSQL').first().json.id;
const parsed = $input.first().json;
const videoList = parsed.data?.videos || parsed.data?.itemList || parsed.data || parsed.itemList || parsed.item_list || [];
if (!videoList.length) { throw new Error('No videos returned. Response: ' + JSON.stringify(parsed).slice(0, 300)); }
let webhookNiche = null;
try { webhookNiche = $('Webhook').first().json.body?.niche || null; } catch(e) { webhookNiche = null; }
const nicheTag = webhookNiche ? webhookNiche.toLowerCase().split('&')[0].trim().replace(/[^a-z0-9 ]/g, '').split(' ')[0] : null;
const results = [];
for (let i = 0; i < Math.min(10, videoList.length); i++) {
  const item = videoList[i];
  const v      = item.video_info || item.video || item;
  const author = item.author_info || item.author || {};
  const stats  = item.stats_info || item.stats || item.statistics || v.stats || v.statistics || {};
  const authorHandle = author.unique_id || author.uniqueId || author.nickname || 'unknown';
  const hashtags = (v.textExtra || item.text_extra || item.textExtra || []).filter(t => t.hashtagName || t.hashtag_name).map(t => '#' + (t.hashtagName || t.hashtag_name));
  const category = nicheTag || hashtags[0]?.replace('#', '') || 'trending';
  const views = stats.playCount || stats.play_count || stats.vv || item.play_count || item.playCount || item.video_play_count || item.view_count || 0;
  const likes = stats.diggCount || stats.digg_count || stats.digg || item.digg_count || item.diggCount || item.like_count || item.likeCount || 0;
  const videoUrl = item.play || '';
  results.push({ json: { run_id: runId, rank: i + 1, video_id: String(item.video_id || item.aweme_id || v.id || item.id || i), title: (item.title || item.content_desc || item.desc || v.desc || '').slice(0, 500), author: '@' + authorHandle, views: String(views), likes: String(likes), video_url: videoUrl, hashtags: hashtags.length ? hashtags : ['#' + (nicheTag || 'trending')], category: category.slice(0, 100), thumbnail_url: (item.cover || v.cover?.url_list?.[0] || v.cover || '').slice(0, 1000), tiktok_url: `https://www.tiktok.com/@${authorHandle}/video/${item.video_id || item.aweme_id || v.id || ''}` } });
}
return results;

const scriptData = $('🗄️ Fetch Approved Script for Posting').first().json;
let scriptJson = {};
try { scriptJson = JSON.parse(scriptData.script_json || '{}'); } catch(e) {}
const videoData = $('🗄️ Mark Video Approved').item.json;
