const fileSizeStr = $binary.data.fileSize;
const parts = fileSizeStr.split(' ');
const value = parseFloat(parts[0]);
const unit = parts[1].toUpperCase();
const multipliers = { 'B': 1, 'KB': 1024, 'MB': 1048576, 'GB': 1073741824 };
const byteSize = Math.floor(value * (multipliers[unit] || 1048576));
return [{ json: { ...$json, videoByteSize: byteSize }, binary: $binary }];

return [{
