const creatorId = query.creatorId || 'unknown';
const scope = encodeURIComponent('user.info.basic,video.list,video.publish,video.upload');
const redirectUri = encodeURIComponent('https://noncartelized-delightsomely-donetta.ngrok-free.dev/webhook/c0a80001-0000-0000-0000-000000000002');
