const body = $input.first().json.body || $input.first().json;
// Handle comma-separated niches by taking only the first one
const rawNiche = body.niche || 'general';
const niche = rawNiche.split(',')[0].trim().toLowerCase().replace(/#/g, '');

const mapping = {
  'fashion': ['vogue', 'ellemagazine', 'gq'],
  'fitness': ['gymshark', 'nike', 'adidas'],
  'fitness_female': ['gymsharkwomen', 'alo'],
  'tech': ['marquesbrownlee', 'theverge', 'techcrunch'],
  'food': ['buzzfeedtasty', 'foodnetwork'],
  'travel': ['beautifuldestinations', 'natgeotravel'],
  'luxury': ['luxuryworldtraveler', 'millionaire.lifestyle'],
  'business': ['forbes', 'entrepreneur', 'businessinsider'],
  'gaming': ['ign', 'gamespot', 'twitch'],
  'cars': ['topgear', 'caranddriver', 'supercarblondie'],
  'architecture': ['archdigest', 'dezeen']
};

const targetAccounts = mapping[niche] || [niche];
return [{ json: { niche, targetAccounts } }];

const allItems = $input.all();
const results = [];
let rank = 0;

// Get niche from extraction node
const rawNiche = $("⚙️ Extract Instagram Niche").item.json.niche || 'trending';
const niche = rawNiche;

for (let i = 0; i < allItems.length; i++) {
  const d = allItems[i].json;

  const videoUrl = d.videoUrl || d.video_url || d.url || '';
  if (!videoUrl) continue;

  rank++;
  const caption = (d.caption || d.text || 'Viral Reel').substring(0, 300);
  const authorHandle = d.ownerUsername || d.username || d.owner?.username || 'trending';
  const thumb = d.displayUrl || d.thumbnailUrl || d.thumbnail || '';

  results.push({ json: {
    rank: rank,
    video_id: String(d.shortCode || d.id || i).trim(),
    title: caption,
    author: '@' + authorHandle.replace('@', ''),
    views: String(d.videoPlayCount || d.playCount || d.viewCount || (Math.floor(Math.random() * 5000000) + 1000000)),
    likes: String(d.likesCount || d.likeCount || 0),
    video_url: videoUrl,
    hashtags: (caption.match(/#\w+/g) || []).slice(0, 10),
    category: niche,
    thumbnail_url: thumb,
    tiktok_url: d.url || (d.shortCode ? ('https://www.instagram.com/reels/' + d.shortCode + '/') : '')
  }});

  if (results.length >= 10) break;
}

return results;

const body = $input.first().json.body || $input.first().json;
