parameters.query:
UPDATE generated_videos SET status = 'approved', approved_at = NOW()
WHERE video_id = '{{ $json.body.videoId }}'
RETURNING video_url, session_id, creator_id;

UPDATE generated_videos SET status = 'declined', declined_at = NOW(), feedback = '{{ $json.body.feedback }}'
WHERE video_id = '{{ $json.body.videoId }}'
RETURNING video_id, session_id, creator_id;

